// Objects
namespace
{
    struct PosColorTexCoord0Vertex
    {
        float x;
        float y;
        float z;
        uint32_t abgr;
        float u;
        float v;

        static void init()
        {
            msLayout
                .begin()
                .add(bgfx::Attrib::Position,  3, bgfx::AttribType::Float)
                .add(bgfx::Attrib::Color0,    4, bgfx::AttribType::Uint8, true)
                .add(bgfx::Attrib::TexCoord0, 2, bgfx::AttribType::Float)
                .end();
        }

        static bgfx::VertexLayout msLayout;
    };

    bgfx::VertexLayout PosColorTexCoord0Vertex::msLayout;

    void renderScreenSpaceQuad(uint8_t _view, bgfx::ProgramHandle _program, float _x, float _y, float _width, float _height)
    {
        bgfx::TransientVertexBuffer tvb;
        bgfx::TransientIndexBuffer tib;

        if (bgfx::allocTransientBuffers(&tvb, PosColorTexCoord0Vertex::msLayout, 4, &tib, 6))
        {
            PosColorTexCoord0Vertex* vertex = (PosColorTexCoord0Vertex*)tvb.data;

            float zz = 0.0f;

            const float minx = _x;
            const float maxx = _x + _width;
            const float miny = _y;
            const float maxy = _y + _height;

            float minu = -1.0f;
            float minv = -1.0f;
            float maxu =  1.0f;
            float maxv =  1.0f;

            vertex[0].x = minx;
            vertex[0].y = miny;
            vertex[0].z = zz;
            vertex[0].abgr = 0xff0000ff;
            vertex[0].u = minu;
            vertex[0].v = minv;

            vertex[1].x = maxx;
            vertex[1].y = miny;
            vertex[1].z = zz;
            vertex[1].abgr = 0xff00ff00;
            vertex[1].u = maxu;
            vertex[1].v = minv;

            vertex[2].x = maxx;
            vertex[2].y = maxy;
            vertex[2].z = zz;
            vertex[2].abgr = 0xffff0000;
            vertex[2].u = maxu;
            vertex[2].v = maxv;

            vertex[3].x = minx;
            vertex[3].y = maxy;
            vertex[3].z = zz;
            vertex[3].abgr = 0xffffffff;
            vertex[3].u = minu;
            vertex[3].v = maxv;

            uint16_t* indices = (uint16_t*)tib.data;

            indices[0] = 0;
            indices[1] = 2;
            indices[2] = 1;
            indices[3] = 0;
            indices[4] = 3;
            indices[5] = 2;

            bgfx::setState(BGFX_STATE_DEFAULT);
            bgfx::setIndexBuffer(&tib);
            bgfx::setVertexBuffer(0, &tvb);
            bgfx::submit(_view, _program);
        }
    }

    struct FrameTime
    {
        ///
        FrameTime()
            : m_start(bx::InitNone)
            , m_last(bx::InitNone)
            , m_current(bx::getNow() )
        {
            reset();
        }

        ///
        void reset()
        {
            m_start = m_current;
            frame();
        }

        ///
        void frame()
        {
            m_last    = m_current;
            m_current = bx::getNow();
        }

        ///
        bx::Ticks getDeltaTime() const
        {
            return m_current - m_last;
        }

        ///
        bx::Ticks getDurationTime() const
        {
            return m_current - m_start;
        }

        bx::Ticks m_start;
        bx::Ticks m_last;
        bx::Ticks m_current;
    };
}

int bgfxRaymarch()
{
    //Create window
    Application::Window window("Raymarching");
    window.Create();

    bgfx::setViewClear(
        0,
        BGFX_CLEAR_COLOR | BGFX_CLEAR_DEPTH,
        0x303030ff,
        1.0f,
        0);

    // Create vertex stream declaration.
    PosColorTexCoord0Vertex::init();

    bgfx::UniformHandle uniformMtx          = bgfx::createUniform("u_mtx",      bgfx::UniformType::Mat4);
    bgfx::UniformHandle uniformLightDirTime = bgfx::createUniform("u_lightDirTime", bgfx::UniformType::Vec4);

    const bgfx::Memory* vShaderData = bgfx::alloc(vertexSourceSize + 1);
    const bgfx::Memory* fShaderData = bgfx::alloc(fragmentSourceSize + 1);
    std::memcpy(vShaderData->data, vertexSource, vertexSourceSize);
    std::memcpy(fShaderData->data, fragmentSource, fragmentSourceSize);
    vShaderData->data[vShaderData->size - 1] = '\0';
    fShaderData->data[fShaderData->size - 1] = '\0';
    
    bgfx::ShaderHandle vertexShaderHandle = bgfx::createShader(vShaderData);
    bgfx::ShaderHandle fragmentShaderHandle = bgfx::createShader(fShaderData);
    // Create program from shaders.
    bgfx::ProgramHandle program = bgfx::createProgram(
        vertexShaderHandle,
        fragmentShaderHandle,
        true);

    FrameTime frameTime;
    frameTime.reset();

    const int width = window.GetWidth();
    const int height = window.GetHeight();

    //Create loop
    bool doStuff = true;
    while (doStuff)
    {
        frameTime.frame();
        const float time = bx::toSeconds<float>(frameTime.getDurationTime() );

        // Sleep if window is not visible
        if (window.GetSDLWindowFlags() & SDL_WINDOW_MINIMIZED)
        {
            SDL_Delay(10);
            continue;
        }

        // -------- Events --------
        SDL_Event event;
        while (SDL_PollEvent(&event))
        {
            ImGui_ImplSDL3_ProcessEvent(&event);

            switch (event.type)
            {
                case SDL_EVENT_QUIT:
                    doStuff = false;
                    break;
                case SDL_EVENT_WINDOW_CLOSE_REQUESTED:
                    doStuff = false;
                    break;
                case SDL_EVENT_WINDOW_RESIZED:
                {
                    window.Refresh();
                    break;
                }
                case SDL_EVENT_KEY_DOWN:
                {
                    // Don't process keyboard events if ImGui has captured the keyboard
                    if (ImGui::GetIO().WantCaptureKeyboard)
                        break;
                    break;
                }
                default: break;
            }
        }

        // -------- ImGui --------
        // ImGui_Implbgfx_NewFrame();
        // ImGui_ImplSDL3_NewFrame();
        // ImGui::NewFrame();
        // ImGui::End();

        // -------- Rendering --------
        // Set view 0 default viewport.
        bgfx::setViewRect(0, 0, 0, uint16_t(width), uint16_t(height) );

        // Set view 1 default viewport.
        bgfx::setViewRect(1, 0, 0, uint16_t(width), uint16_t(height) );

        // This dummy draw call is here to make sure that view 0 is cleared
        // if no other draw calls are submitted to viewZ 0.
        bgfx::touch(0);

        const bx::Vec3 at  = { 0.0f, 0.0f,   0.0f };
        const bx::Vec3 eye = { 0.0f, 0.0f, -15.0f };

        float view[16];
        float proj[16];
        bx::mtxLookAt(view, eye, at);

        const bgfx::Caps* caps = bgfx::getCaps();
        bx::mtxProj(proj, 60.0f, float(width)/float(height), 0.1f, 100.0f, caps->homogeneousDepth);

        // Set view and projection matrix for view 1.
        bgfx::setViewTransform(0, view, proj);

        float ortho[16];
        bx::mtxOrtho(ortho, 0.0f, 1280.0f, 720.0f, 0.0f, 0.0f, 100.0f, 0.0, caps->homogeneousDepth);

        // Set view and projection matrix for view 0.
        bgfx::setViewTransform(1, NULL, ortho);

        float vp[16];
        bx::mtxMul(vp, view, proj);

        float mtx[16];
        bx::mtxRotateXY(mtx
            , time
            , time*0.37f
            );

        float mtxInv[16];
        bx::mtxInverse(mtxInv, mtx);
        float lightDirTime[4];
        const bx::Vec3 lightDirModelN = bx::normalize(bx::Vec3{-0.4f, -0.5f, -1.0f});
        bx::store(lightDirTime, bx::mul(lightDirModelN, mtxInv) );
        lightDirTime[3] = time;
        bgfx::setUniform(uniformLightDirTime, lightDirTime);

        float mvp[16];
        bx::mtxMul(mvp, mtx, vp);

        float invMvp[16];
        bx::mtxInverse(invMvp, mvp);
        bgfx::setUniform(uniformMtx, invMvp);

        renderScreenSpaceQuad(1, program, 0.0f, 0.0f, 1280.0f, 720.0f);

        // Advance to next frame. Rendering thread will be kicked to
        // process submitted rendering primitives.
        // ImGui::Render();
        // ImGui_Implbgfx_RenderDrawLists(ImGui::GetDrawData());
        bgfx::frame();
    }

    // Cleanup
    bgfx::destroy(program);
    bgfx::destroy(uniformMtx);
    bgfx::destroy(uniformLightDirTime);

    window.Destroy();

    return EXIT_SUCCESS;
}
